import React, { useState } from "react";
import axios from "axios";

const GoogleWalletIntegration = () => {
  const [saveLink, setSaveLink] = useState("");

  const createEventTicket = async () => {
    try {
      // Hacer una solicitud al backend para crear el ticket
      const response = await axios.post("http://localhost:5000/create-ticket");
      setSaveLink(response.data.saveLink); // Guardar la URL de guardado
    } catch (error) {
      console.error("Error creating event ticket:", error);
    }
  };

  return (
    <div>
      <h1>Google Wallet Event Ticket Integration</h1>
      <button onClick={createEventTicket}>Create Event Ticket</button>
      {saveLink && (
        <div>
          <p>Ticket created successfully!</p>
          <a href={saveLink} target="_blank" rel="noopener noreferrer">
            Add to Google Wallet
          </a>
        </div>
      )}
    </div>
  );
};

export default GoogleWalletIntegration;
